DELETE FROM jhi_user_authority;


DELETE FROM jhi_user WHERE login NOT IN ('admin@sansfile.sn', 'admin');


DELETE FROM jhi_user WHERE login = 'admin' AND EXISTS (SELECT 1 FROM jhi_user WHERE login = 'admin@sansfile.sn');


UPDATE jhi_user SET login = 'admin@sansfile.sn' WHERE login = 'admin';


INSERT INTO jhi_user (id, login, password_hash, first_name, last_name, email, phone, activated, lang_key, created_by, created_date)
SELECT 1051, 'admin@sansfile.sn', '$2a$10$hVxUkycZbtw.Vc7WTaRWp.mtEEu7O0vr.QTpYRluFs0t/cyyyrUyW', 'Super', 'Admin', 'contact@sansfile.sn', '+221778627052', true, 'fr', 'system', NOW()
WHERE NOT EXISTS (SELECT 1 FROM jhi_user WHERE login = 'admin@sansfile.sn');


UPDATE jhi_user
SET phone = '+221778627052',
    email = 'contact@sansfile.sn',
    first_name = 'Super',
    last_name = 'Admin',
    activated = true
WHERE login = 'admin@sansfile.sn';


INSERT INTO jhi_user_authority (user_id, authority_name)
SELECT u.id, a.name
FROM jhi_user u
CROSS JOIN jhi_authority a
WHERE u.login = 'admin@sansfile.sn'
  AND a.name IN ('ROLE_ADMIN', 'ROLE_SUPER_ADMIN', 'ROLE_USER')
ON CONFLICT DO NOTHING;


UPDATE platform_settings
SET contact_phone = '+221 77 862 70 52',
    contact_email = 'contact@sansfile.sn';
